import React, { useState } from 'react';
import MissionControlSidebar from '@/components/MissionControlSidebar';
import MissionControlCanvas from '@/components/MissionControlCanvas';

type ProjectContext = 'OVERALL_GROUP' | 'CHIEF_MADOTHI' | 'DEFEND_YOUR_FAITH' | 'MYTHOLOGY_SUBS' | 'STEDT_TYRONE';
type ActiveScreen = 'KANBAN' | 'CALENDAR' | 'PROJECTS' | 'BOARDROOM' | 'CAMPAIGNS' | 'OBSIDIAN' | 'PAPERCLIP' | 'SECURITY';

export default function MissionControlLayout() {
 const [context, setContext] = useState<ProjectContext>('OVERALL_GROUP');
 const [activeScreen, setActiveScreen] = useState<ActiveScreen>('KANBAN');

 const contextLabels: Record<ProjectContext, string> = {
 OVERALL_GROUP: 'Overall Group Operations',
 CHIEF_MADOTHI: "Chief Madothi Children's School & Feeding Fund",
 DEFEND_YOUR_FAITH: 'Defend Your Faith Digital eBooks',
 MYTHOLOGY_SUBS: 'Mythology Subscription Engines',
 STEDT_TYRONE: 'STEDT Tyrone Commission Pipelines'
 };

 return (
 <div className="w-screen h-screen overflow-hidden bg-rhythm-obsidian-deep text-rhythm-silver-mist font-mono flex flex-col select-none antialiased">
 <header className="h-16 w-full bg-rhythm-charcoal-matte border-b border-rhythm-slate-reflection/20 px-6 flex items-center justify-between z-50">
 <div className="flex items-center space-x-3">
 <div className="w-2 h-2 rounded-full bg-rhythm-goldenrod-core animate-pulse" />
 <h1 className="text-[#E2E8F0] uppercase tracking-[0.05em] font-bold text-sm">
 WASP // Rhythm Nerve Center
 </h1>
 </div>

 <div className="flex items-center space-x-4">
 <span className="text-[11px] text-rhythm-sage-metallic uppercase tracking-wider">Context Selector:</span>
 <div className="relative">
 <select
 value={context}
 onChange={(e) => setContext(e.target.value as ProjectContext)}
 className="bg-rhythm-glass-specular border border-rhythm-slate-reflection/40 text-[#C5A059] font-mono text-xs rounded-sm px-4 py-2 outline-none cursor-pointer hover:border-rhythm-gold-liquid/40 transition-colors duration-200 uppercase tracking-wide appearance-none pr-8 font-bold"
 >
 <option value="OVERALL_GROUP">🌐 Overall Group</option>
 <option value="CHIEF_MADOTHI">🦁 Chief Madothi</option>
 <option value="DEFEND_YOUR_FAITH">🛡️ Defend Faith</option>
 <option value="MYTHOLOGY_SUBS">🏛️ Mythology Subs</option>
 <option value="STEDT_TYRONE">📈 STEDT Tyrone</option>
 </select>
 <div className="absolute right-3 top-3.5 pointer-events-none text-rhythm-gold-liquid text-[9px]">▼</div>
 </div>
 </div>
 </header>

 <div className="h-[1px] w-full bg-gradient-to-r from-transparent via-rhythm-gold-liquid/40 to-transparent" />

 <div className="flex-1 flex w-full overflow-hidden">
 <MissionControlSidebar activeScreen={activeScreen} setActiveScreen={setActiveScreen} />
 <MissionControlCanvas context={context} activeScreen={activeScreen} contextLabels={contextLabels} />
 </div>
 </div>
 );
}

